using System.ComponentModel;
using System.Text.Json;

namespace McpHttpServer;

[McpServerResourceType]
public static class ConfigResource
{
    [McpServerResource(Uri = "config://app/database", Name = "Database Config",
        Description = "Returns database configuration", MimeType = "application/json")]
    public static string GetDatabaseConfig()
    {
        var config = new { ConnectionTimeout = 30, MaxPoolSize = 100, Provider = "PostgreSQL" };
        return JsonSerializer.Serialize(config, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(Uri = "config://app/logging", Name = "Logging Config",
        Description = "Returns logging configuration", MimeType = "application/json")]
    public static string GetLoggingConfig()
    {
        var config = new { Level = "Information", Format = "json", Sink = "Console" };
        return JsonSerializer.Serialize(config, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(Uri = "config://app/features", Name = "Feature Flags",
        Description = "Returns feature flag configuration", MimeType = "application/json")]
    public static string GetFeatureFlags()
    {
        var config = new { DarkMode = true, BetaAccess = false, MaxUploadMb = 50 };
        return JsonSerializer.Serialize(config, new JsonSerializerOptions { WriteIndented = true });
    }
}

