using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Text.Json;

namespace McpHttpServer;

[McpServerResource(Name = "config://app",
    Description = "Returns the current application configuration data")]
public static class ConfigResource
{
    [McpServerResourceTemplate(UriTemplate = "config://app/{section}",
        Name = "App Configuration",
        Description = "Returns configuration for a given section",
        MimeType = "application/json")]
    public static string GetConfig(string section)
    {
        // In production, load from IConfiguration or a database
        var config = section.ToLowerInvariant() switch
        {
            "database" => new { ConnectionTimeout = 30, MaxPoolSize = 100, Provider = "PostgreSQL" },
            "logging" => new { Level = "Information", Format = "json", Sink = "Console" } as object,
            "features" => new { DarkMode = true, BetaAccess = false, MaxUploadMb = 50 },
            _ => new { Error = $"Unknown section: {section}" }
        };

        return JsonSerializer.Serialize(config, new JsonSerializerOptions { WriteIndented = true });
    }
}

